def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid vertical divider.
    div = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
    n = min(div, w - div - 1)
    left = [row[:n] for row in grid]
    right = [row[div + 1:div + 1 + n] for row in grid]

    def most_common(values):
        return max(set(values), key=values.count)

    left_bg = most_common([v for row in left for v in row])
    right_bg = most_common([v for row in right for v in row])

    return [
        [3 if left[r][c] != left_bg and right[r][c] == right_bg else right_bg
         for c in range(n)]
        for r in range(h)
    ]
